const seedStudents=[['Alya Putri','240101','VII A','Perempuan','Aktif'],['Bima Pratama','240102','VII A','Laki-laki','Aktif'],['Citra Maharani','240103','VII A','Perempuan','Aktif'],['Daffa Ramadhan','240104','VII A','Laki-laki','Aktif'],['Eka Safitri','240105','VII B','Perempuan','Aktif'],['Farhan Akbar','240106','VII B','Laki-laki','Aktif'],['Gita Permata','240107','VIII A','Perempuan','Aktif'],['Hafiz Nugraha','240108','VIII A','Laki-laki','Aktif'],['Intan Lestari','240109','VIII B','Perempuan','Aktif'],['Joko Santoso','240110','VIII B','Laki-laki','Aktif'],['Kirana Dewi','240111','IX A','Perempuan','Aktif'],['Lukman Hakim','240112','IX A','Laki-laki','Aktif']].map(([nama,nis,kelas,gender,status],i)=>({id:nis,nama,nis,kelas,gender,status,initial:nama.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),scores:[78+i%8,82-i%6,85+i%7]}));
const seedSchedule=[{hari:'Senin',waktu:'07.00',kelas:'VII A',materi:'Sepak bola',lokasi:'Lapangan utama',warna:'green'},{hari:'Senin',waktu:'09.30',kelas:'VIII A',materi:'Bola voli',lokasi:'Lapangan utama',warna:'orange'},{hari:'Selasa',waktu:'08.00',kelas:'VII B',materi:'Kebugaran jasmani',lokasi:'Aula olahraga',warna:'blue'},{hari:'Rabu',waktu:'10.00',kelas:'IX A',materi:'Atletik — lari jarak pendek',lokasi:'Lintasan',warna:'green'}];
const seedGrades=[{id:'g1',nama:'Alya Putri',nis:'240101',kelas:'VII A',materi:'Sepak bola',kategori:'Keterampilan praktik',komponen:'Passing',score:88,bobot:100,semester:'Ganjil',catatan:'Kontrol bola semakin konsisten.'},{id:'g2',nama:'Bima Pratama',nis:'240102',kelas:'VII A',materi:'Sepak bola',kategori:'Keterampilan praktik',komponen:'Dribbling',score:82,bobot:100,semester:'Ganjil',catatan:'Terus latih perubahan arah.'},{id:'g3',nama:'Citra Maharani',nis:'240103',kelas:'VII A',materi:'Kebugaran jasmani',kategori:'Kebugaran jasmani',komponen:'Daya tahan',score:91,bobot:100,semester:'Ganjil',catatan:'Menunjukkan usaha yang baik.'},{id:'g4',nama:'Gita Permata',nis:'240107',kelas:'VIII A',materi:'Bola voli',kategori:'Keterampilan praktik',komponen:'Passing bawah',score:86,bobot:100,semester:'Ganjil',catatan:'Posisi siap sudah baik.'}];
const seedAttendance={};
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('pjok_'+k))??d}catch{return d}};
let students=get('students',seedStudents), classes=get('classes',['VII A','VII B','VIII A','VIII B','IX A']), grades=get('grades',seedGrades), schedule=get('schedule',seedSchedule), attendance=get('attendance',seedAttendance), view='Dashboard', filterClass='Semua kelas', search='', editing=null, activeDay='Senin';
const persist=()=>{localStorage.setItem('pjok_students',JSON.stringify(students));localStorage.setItem('pjok_classes',JSON.stringify(classes));localStorage.setItem('pjok_grades',JSON.stringify(grades));localStorage.setItem('pjok_schedule',JSON.stringify(schedule));localStorage.setItem('pjok_attendance',JSON.stringify(attendance))};
const icons={Dashboard:'dashboard',Siswa:'groups',Kelas:'grid_view',Jadwal:'calendar_month',Presensi:'fact_check',Penilaian:'equalizer',Materi:'menu_book',Tugas:'assignment',Laporan:'analytics',Pengaturan:'settings'};
const navItems=[['MENU UTAMA','Dashboard','Siswa','Kelas','Jadwal'],['PEMBELAJARAN','Presensi','Penilaian','Materi','Tugas'],['LAINNYA','Laporan','Pengaturan']];
const today=new Date();const dateText=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(today);const shortDate=today.toISOString().slice(0,10);
function icon(name){return `<span class="material-symbols-rounded" aria-hidden="true">${name}</span>`}
function shell(){document.getElementById('app').innerHTML=`<div class="shell"><aside id="sidebar" class="sidebar"><div class="brand"><div class="brand-mark">${icon('sports_soccer')}</div><div><div class="brand-name">PJOK SMART</div><div class="brand-sub">Asisten Digital Guru PJOK</div></div></div>${navItems.map(group=>`<div class="nav-label">${group[0]}</div><nav class="nav">${group.slice(1).map(n=>`<button class="${view===n?'active':''}" data-nav="${n}">${icon(icons[n])}<span>${n==='Siswa'?'Data Siswa':n==='Materi'?'Materi PJOK':n==='Tugas'?'Tugas & Kuis':n}</span></button>`).join('')}</nav>`).join('')}<div class="side-bottom"><div class="help-card"><strong>Butuh bantuan?</strong>Temukan panduan singkat menggunakan PJOK SMART.<br><button data-action="help">Lihat panduan ${icon('arrow_forward')}</button></div><div class="profile-mini"><div class="avatar">DG</div><div><strong style="font-size:11px">Dewi Guru, S.Pd.</strong><small>Guru PJOK · SMP</small></div>${icon('more_vert')}</div></div></aside><main class="main"><div class="mobile-head"><button class="icon-btn" data-action="menu" aria-label="Buka menu">${icon('menu')}</button><div class="brand"><div class="brand-mark">${icon('sports_soccer')}</div><div><div class="brand-name">PJOK SMART</div><div class="brand-sub">Asisten Digital Guru PJOK</div></div></div><div class="avatar">DG</div></div><header class="topbar"><div class="crumb">Beranda <span style="color:#c3ccd7">/</span> <strong style="color:#435770">${view==='Siswa'?'Data Siswa':view==='Materi'?'Materi PJOK':view==='Tugas'?'Tugas & Kuis':view}</strong></div><div class="top-actions"><label class="search">${icon('search')}<input id="global-search" placeholder="Cari siswa, kelas..." value="${esc(search)}" aria-label="Pencarian" /></label><button class="icon-btn" data-action="notify" aria-label="Notifikasi">${icon('notifications')}<i class="dot"></i></button><div class="avatar">DG</div></div></header><section id="page" class="page">${renderPage()}</section></main></div>${sessionStorage.getItem('pjok_logged')?'':loginMarkup()}`; bind()}
function loginMarkup(){return `<div class="overlay-login"><div class="login-box"><div class="brand"><div class="brand-mark">${icon('sports_soccer')}</div><div><div class="brand-name">PJOK SMART</div><div class="brand-sub">Mengajar Lebih Mudah, Siswa Lebih Aktif.</div></div></div><h1>Selamat datang!</h1><p>Masuk ke ruang kerja digital pembelajaran PJOK Anda.</p><form id="login-form"><div class="field"><label for="login-email">Email</label><input id="login-email" type="email" value="guru@pjoksmart.id" autocomplete="username" required /></div><div class="field"><label for="login-pass">Kata sandi</label><input id="login-pass" type="password" value="demoguru" autocomplete="current-password" required /></div><button class="btn btn-primary" style="width:100%;margin-top:4px">Masuk ke dashboard ${icon('arrow_forward')}</button></form><div class="demo-note">Mode demo: gunakan email dan kata sandi contoh yang sudah terisi. Tidak ada kredensial yang dikirim atau disimpan.</div></div></div>`}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function heading(title,desc,action=''){return `<div class="welcome-row"><div><div class="eyebrow">${view==='Dashboard'?'RUANG KERJA GURU':`MANAJEMEN PEMBELAJARAN`}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p></div>${action}</div>`}
function btn(label,action,kind='btn-primary',ico='add'){return `<button class="btn ${kind}" data-action="${action}">${icon(ico)}${label}</button>`}
function stat(label,num,ico,tint,foot){return `<article class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon ${tint}">${icon(ico)}</span></div><div class="stat-num">${num}</div><div class="stat-foot">${foot}</div></article>`}
function renderPage(){switch(view){case'Dashboard':return dashboard();case'Siswa':return studentsPage();case'Detail siswa':return detailPage();case'Kelas':return classesPage();case'Jadwal':return schedulePage();case'Presensi':return attendancePage();case'Penilaian':return gradesPage();case'Materi':return materialsPage();case'Tugas':return tasksPage();case'Laporan':return reportsPage();case'Pengaturan':return settingsPage();default:return dashboard()}}
function dashboard(){let n=students.length,att=attendance[shortDate]||{},present=Object.values(att).filter(x=>x.status==='Hadir').length;let ratio=Object.keys(att).length?Math.round(present/Object.keys(att).length*100):92;return `${heading('Selamat pagi, Bu Dewi!','Siap membuat siswa lebih aktif hari ini?','<div class="date-chip">'+icon('calendar_today')+' &nbsp;'+dateText+'</div>')}<div class="welcome-row" style="margin-top:-10px;margin-bottom:16px"><div class="eyebrow" style="color:#8390a2;text-transform:none;letter-spacing:0">Ringkasan aktivitas belajar Anda</div><div class="actions">${btn('Tambah siswa','add-student','btn-light','person_add')}${btn('Isi presensi','go-attendance','btn-green','fact_check')}${btn('Input nilai','add-grade','btn-primary','edit_note')}</div></div><div class="stats">${stat('Total siswa',n, 'groups','tint-blue','Terdaftar di semua kelas')}${stat('Kelas diajar',classes.length,'grid_view','tint-purple',classNames().slice(0,4).join(', '))}${stat('Kehadiran hari ini',Object.keys(att).length?`${ratio}%`:'92%','task_alt','tint-green',Object.keys(att).length?`${present} dari ${Object.keys(att).length} tercatat`:'Rata-rata minggu ini')}${stat('Penilaian tertunda','3','assignment_late','tint-orange','Perlu diselesaikan minggu ini')}</div><div class="grid-main"><article class="card panel"><div class="panel-head"><div><div class="panel-title">Perkembangan nilai siswa</div><div class="panel-sub">Rata-rata nilai praktik per bulan</div></div><select class="select-sm" aria-label="Semester"><option>Semester Ganjil</option><option>Semester Genap</option></select></div><div class="chart">${lineChart()}</div><div class="legend"><span><i style="background:#38b76b"></i>Rata-rata nilai</span><span><i style="background:#ff9f43"></i>Target belajar</span></div></article><article class="card panel"><div class="panel-head"><div><div class="panel-title">Ringkasan kehadiran</div><div class="panel-sub">Rekap kehadiran kelas bulan ini</div></div><button class="mini-btn" data-nav="Laporan">${icon('more_horiz')}</button></div><div class="attendance-content"><div class="donut-wrap"><div class="donut"></div><div class="donut-center"><strong>${Object.keys(att).length?ratio:92}%</strong><small>KEHADIRAN</small></div></div><div class="att-legend"><div class="att-line"><span><i style="background:#38b76b"></i>Hadir</span><b>92%</b></div><div class="att-line"><span><i style="background:#f4b45a"></i>Izin</span><b>4%</b></div><div class="att-line"><span><i style="background:#88a3c2"></i>Sakit</span><b>3%</b></div><div class="att-line"><span><i style="background:#e7ebf0"></i>Alpa</span><b>1%</b></div></div></div></article></div><div class="lower-grid"><article class="card panel"><div class="panel-head"><div><div class="panel-title">Jadwal pelajaran hari ini</div><div class="panel-sub">Agenda pembelajaran PJOK</div></div><button class="btn btn-light" data-nav="Jadwal" style="padding:7px 9px;font-size:10px">Lihat jadwal ${icon('arrow_forward')}</button></div>${(schedule.filter(x=>x.hari===new Intl.DateTimeFormat('id-ID',{weekday:'long'}).format(today))).slice(0,3).map(s=>`<div class="schedule-item"><div class="time">${s.waktu}<br/>${s.waktu==='07.00'?'08.20':'10.50'}</div><div class="lesson ${s.warna==='orange'?'orange':s.warna==='blue'?'blue':''}"><strong>${s.kelas} · ${s.materi}</strong><small>${s.lokasi} · PJOK</small></div><span class="pill ${s.warna==='orange'?'orange':s.warna==='blue'?'blue':''}">Terjadwal</span></div>`).join('')||`<div class="empty">${icon('event_available')}<p>Tidak ada kelas terjadwal hari ini.</p></div>`}</article><article class="card panel"><div class="panel-head"><div><div class="panel-title">Aktivitas terbaru</div><div class="panel-sub">Pembaruan dari kelas Anda</div></div><button class="mini-btn" data-nav="Laporan">${icon('more_horiz')}</button></div><div class="activity"><div class="activity-icon">${icon('task_alt')}</div><div><strong>Presensi VII A berhasil dicatat</strong><small>Hari ini · Data contoh</small></div></div><div class="activity"><div class="activity-icon" style="background:#fff3e5;color:#e99a3d">${icon('edit_note')}</div><div><strong>Nilai praktik sepak bola diperbarui</strong><small>Kemarin, 14.32 · 12 siswa</small></div></div><div class="activity"><div class="activity-icon" style="background:#edf3fb;color:#5784b4">${icon('menu_book')}</div><div><strong>Materi kebugaran jasmani dibuka</strong><small>Senin, 09.15 · VIII A</small></div></div></article></div><div class="card" style="margin-top:16px;padding:14px 17px;display:flex;align-items:center;justify-content:space-between;gap:12px"><div style="font-size:10px;color:#8290a1">${icon('info')} &nbsp;Data contoh untuk demonstrasi. Perubahan tersimpan lokal di browser ini.</div><button class="btn btn-light" style="padding:7px 9px;font-size:10px" data-nav="Laporan">Lihat analitik ${icon('arrow_forward')}</button></div>`}
function lineChart(){return `<svg viewBox="0 0 560 200" role="img" aria-label="Grafik rata-rata nilai meningkat dari Januari sampai Juni"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#38b76b" stop-opacity=".18"/><stop offset="1" stop-color="#38b76b" stop-opacity="0"/></linearGradient></defs>${[30,70,110,150].map(y=>`<path d="M38 ${y} H548" stroke="#edf1f5" stroke-width="1"/>`).join('')}<path d="M38 150 L140 127 L242 139 L344 91 L446 99 L548 49 L548 170 L38 170Z" fill="url(#area)"/><path d="M38 150 L140 127 L242 139 L344 91 L446 99 L548 49" fill="none" stroke="#38b76b" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M38 130 L140 120 L242 109 L344 99 L446 88 L548 77" fill="none" stroke="#ff9f43" stroke-width="2" stroke-dasharray="5 5"/>${[[38,150],[140,127],[242,139],[344,91],[446,99],[548,49]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="#38b76b" stroke-width="2"/>`).join('')}${['Jan','Feb','Mar','Apr','Mei','Jun'].map((m,i)=>`<text x="${38+i*102}" y="190" font-size="10" fill="#94a0af" text-anchor="middle">${m}</text>`).join('')}<text x="5" y="34" font-size="9" fill="#a2adba">100</text><text x="12" y="74" font-size="9" fill="#a2adba">80</text><text x="12" y="114" font-size="9" fill="#a2adba">60</text><text x="12" y="154" font-size="9" fill="#a2adba">40</text></svg>`}
function studentsPage(){const list=students.filter(s=>(filterClass==='Semua kelas'||s.kelas===filterClass)&&(`${s.nama} ${s.nis}`.toLowerCase().includes(search.toLowerCase())));return `${heading('Data siswa','Kelola informasi dan status siswa di kelas PJOK.',btn('Tambah siswa','add-student'))}<div class="card table-card"><div class="table-toolbar"><div class="toolbar-left"><label class="search toolbar-search">${icon('search')}<input id="student-search" placeholder="Cari nama atau nomor induk..." value="${esc(search)}" /></label><select id="class-filter" class="select-sm"><option>Semua kelas</option>${classNames().map(c=>`<option ${filterClass===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="toolbar-right">${btn('Impor CSV','import-csv','btn-light','upload_file')}${btn('Ekspor CSV','students-csv','btn-light','download')}</div></div><div class="table-wrap"><table><thead><tr><th>Nama siswa</th><th>Nomor induk</th><th>Kelas</th><th>Jenis kelamin</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${list.map(s=>`<tr><td><button class="student-cell" data-student="${s.id}" style="background:none;border:0;padding:0;text-align:left"><span class="avatar">${esc(s.initial)}</span><strong>${esc(s.nama)}</strong></button></td><td>${esc(s.nis)}</td><td>${esc(s.kelas)}</td><td>${esc(s.gender)}</td><td><span class="status ${s.status==='Aktif'?'status-active':'status-inactive'}">${s.status}</span></td><td><div class="table-actions"><button class="mini-btn" data-student="${s.id}" aria-label="Lihat detail">${icon('visibility')}</button><button class="mini-btn" data-edit-student="${s.id}" aria-label="Edit siswa">${icon('edit')}</button><button class="mini-btn" data-delete-student="${s.id}" aria-label="Hapus siswa">${icon('delete')}</button></div></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">${icon('person_search')}<p>Tidak ada siswa yang cocok dengan pencarian.</p></div></td></tr>`}</tbody></table></div><div class="pager"><span>Menampilkan ${list.length?1:0}–${list.length} dari ${students.length} siswa</span><div class="pagination"><button class="active">1</button><button disabled>2</button><button disabled>›</button></div></div></div>`}
function classNames(){return [...new Set([...classes,...students.map(s=>s.kelas)])].sort()}
function detailPage(){let s=students.find(x=>x.id===selectedStudent)||students[0];if(!s){view='Siswa';return studentsPage()}let gs=grades.filter(g=>g.nis===s.nis);return `${heading('Detail siswa','Profil siswa dan perkembangan pembelajaran.','<button class="btn btn-light" data-nav="Siswa">'+icon('arrow_back')+' Kembali ke data siswa</button>')}<div class="card panel"><div class="detail-head"><div class="avatar">${esc(s.initial)}</div><div style="flex:1"><div class="panel-title">${esc(s.nama)}</div><div class="panel-sub">NIS ${esc(s.nis)} · Kelas ${esc(s.kelas)} · ${esc(s.gender)}</div></div>${btn('Edit data','edit-current','btn-light','edit')}</div></div><div class="grid-main" style="margin-top:15px"><div class="card panel"><div class="panel-title">Ringkasan belajar</div><div class="bars">${(s.scores||[78,82,86]).map((v,i)=>`<div class="bars-col"><b>${v}</b><i style="height:${v}%"></i><small>${['Mar','Apr','Mei'][i]}</small></div>`).join('')}</div><div class="panel-sub">Nilai penilaian yang sudah dicatat · Data contoh</div></div><div class="card panel"><div class="panel-title">Nilai dan catatan</div>${gs.map(g=>`<div class="schedule-item"><div class="time">${g.score}</div><div class="lesson"><strong>${esc(g.materi)} · ${esc(g.komponen)}</strong><small>${esc(g.catatan||'Belum ada catatan')}</small></div></div>`).join('')||'<div class="empty">Belum ada nilai yang dicatat.</div>'}</div></div>`}
let selectedStudent=null;
function classesPage(){return `${heading('Kelas PJOK','Kelola kelompok belajar dan informasi kelas.',btn('Tambah kelas','add-class'))}<div class="grid-main" style="grid-template-columns:1fr 1fr">${classNames().map((c,i)=>{let count=students.filter(s=>s.kelas===c).length,sch=schedule.find(x=>x.kelas===c);return `<article class="card panel"><div style="display:flex;justify-content:space-between"><span class="stat-icon ${['tint-blue','tint-green','tint-orange','tint-purple'][i%4]}">${icon('groups')}</span><button class="mini-btn" data-class="${c}">${icon('more_horiz')}</button></div><div class="panel-title" style="margin-top:14px">Kelas ${c}</div><div class="panel-sub">${count} siswa terdaftar · Tingkat ${c.split(' ')[0]}</div><div class="schedule-item" style="margin-top:8px"><div class="time">${sch?.waktu||'—'}</div><div class="lesson"><strong>${sch?.materi||'Belum ada jadwal'}</strong><small>${sch?.lokasi||'Atur lokasi belajar'} · ${sch?.hari||'Jadwal belum dibuat'}</small></div><button class="mini-btn" data-class-students="${c}" aria-label="Lihat siswa">${icon('arrow_forward')}</button></div><button class="btn btn-light" data-class-students="${c}" style="width:100%">Lihat siswa ${icon('arrow_forward')}</button></article>`}).join('')}</div>`}
function schedulePage(){return `${heading('Jadwal pelajaran','Atur waktu, kelas, materi, dan lokasi pembelajaran.',btn('Tambah jadwal','add-schedule'))}<div class="subnav">${['Senin','Selasa','Rabu','Kamis','Jumat'].map(d=>`<button class="${activeDay===d?'active':''}" data-day="${d}">${d}</button>`).join('')}</div><div class="card panel">${schedule.filter(s=>s.hari===activeDay).sort((a,b)=>a.waktu.localeCompare(b.waktu)).map((s,i)=>`<div class="schedule-item"><div class="time">${s.waktu}<br/><span style="font-weight:400">${i?'90':'80'} mnt</span></div><div class="lesson ${s.warna==='orange'?'orange':s.warna==='blue'?'blue':''}"><strong>${s.kelas} · ${s.materi}</strong><small>${s.lokasi} · ${activeDay}</small></div><div class="table-actions"><button class="mini-btn" data-edit-schedule="${schedule.indexOf(s)}">${icon('edit')}</button><button class="mini-btn" data-del-schedule="${schedule.indexOf(s)}">${icon('delete')}</button></div></div>`).join('')||'<div class="empty">'+icon('event_busy')+'<p>Belum ada jadwal untuk hari '+activeDay+'.</p></div>'}</div><p class="panel-sub" style="padding:10px">Pilih hari untuk melihat agenda. Semua perubahan disimpan di browser ini.</p>`}
function attendancePage(){let d=document.getElementById('attendance-date')?.value||shortDate,c=document.getElementById('attendance-class')?.value||classNames()[0]||'VII A',ls=students.filter(s=>s.kelas===c),records=attendance[d]||{};return `${heading('Presensi digital','Catat kehadiran siswa dan pantau rekap kelas.') }<div class="card panel" style="margin-bottom:14px"><div class="attendance-controls"><label class="field"><span class="page-desc">Pilih kelas</span><select id="attendance-class">${classNames().map(x=>`<option ${x===c?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span class="page-desc">Tanggal</span><input type="date" id="attendance-date" value="${d}" /></label><div style="margin-left:auto;display:flex;gap:7px">${btn('Tandai semua hadir','all-present','btn-green','done_all')}${btn('Simpan presensi','save-attendance','btn-primary','save')}</div></div></div><div class="card table-card"><div class="table-toolbar"><div><div class="panel-title">Daftar siswa · ${c}</div><div class="panel-sub">Pilih status kehadiran untuk setiap siswa</div></div><div class="toolbar-right">${btn('Ekspor rekap','attendance-csv','btn-light','download')}</div></div><div class="table-wrap"><table><thead><tr><th>Nama siswa</th><th>NIS</th><th>Status kehadiran</th><th>Catatan</th></tr></thead><tbody>${ls.map(s=>{let rec=records[s.nis]||{};return `<tr><td><div class="student-cell"><span class="avatar">${esc(s.initial)}</span><strong>${esc(s.nama)}</strong></div></td><td>${esc(s.nis)}</td><td><select class="select-sm attend-status" data-nis="${s.nis}"><option ${rec.status==='Hadir'?'selected':''}>${rec.status||'Hadir'}</option>${['Hadir','Izin','Sakit','Alpa'].filter(x=>x!==(rec.status||'Hadir')).map(x=>`<option>${x}</option>`).join('')}</select></td><td><input class="att-note" data-nis="${s.nis}" value="${esc(rec.note||'')}" placeholder="Tambahkan catatan" style="border:1px solid var(--line);padding:7px 9px;border-radius:7px;font-size:10px" /></td></tr>`}).join('')}</tbody></table></div><div class="pager"><span>${ls.length} siswa · Perubahan belum disimpan</span><span class="panel-sub">Status akan tersimpan lokal pada browser ini.</span></div></div>`}
function gradesPage(){let c=document.getElementById('grade-class')?.value||'Semua kelas',filtered=grades.filter(g=>c==='Semua kelas'||g.kelas===c);return `${heading('Penilaian PJOK','Catat nilai teori, praktik, kebugaran, dan sikap.',btn('Input nilai','add-grade'))}<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Nilai tercatat',grades.length,'edit_note','tint-blue','Dari seluruh kelas')}${stat('Rata-rata nilai',grades.length?Math.round(grades.reduce((a,g)=>a+Number(g.score||0),0)/grades.length):'—','trending_up','tint-green','Berdasarkan nilai tersimpan')}${stat('Kategori aktif','4','category','tint-orange','Teori · praktik · kebugaran · sikap')}</div><div class="card table-card"><div class="table-toolbar"><div><div class="panel-title">Rekap penilaian</div><div class="panel-sub">Nilai akhir transparan: Σ (skor komponen × bobot) ÷ Σ bobot.</div></div><div class="toolbar-right"><select id="grade-class" class="select-sm"><option>Semua kelas</option>${classNames().map(x=>`<option ${c===x?'selected':''}>${x}</option>`).join('')}</select>${btn('Ekspor CSV','grades-csv','btn-light','download')}</div></div><div class="table-wrap"><table><thead><tr><th>Nama siswa</th><th>Kelas</th><th>Materi & rubrik</th><th>Kategori</th><th>Skor</th><th>Bobot</th><th>Catatan perkembangan</th><th>Aksi</th></tr></thead><tbody>${filtered.map(g=>`<tr><td><strong>${esc(g.nama)}</strong></td><td>${esc(g.kelas)}</td><td>${esc(g.materi)} · ${esc(g.komponen)}</td><td>${esc(g.kategori)}</td><td><strong>${g.score}</strong></td><td>${g.bobot}%</td><td>${esc(g.catatan||'—')}</td><td><button class="mini-btn" data-edit-grade="${g.id}">${icon('edit')}</button><button class="mini-btn" data-del-grade="${g.id}">${icon('delete')}</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">Belum ada nilai untuk filter ini.</div></td></tr>'}</tbody></table></div><div class="pager"><span>Nilai praktik dinilai guru menggunakan rubrik yang dipilih.</span><button class="btn btn-light" style="font-size:10px;padding:7px" data-action="weights">Atur bobot & kategori ${icon('tune')}</button></div></div>`}
function materialsPage(){let mats=[['Sepak bola','sports_soccer','Teknik passing, dribbling, shooting, dan kerja sama tim.'],['Bola voli','sports_volleyball','Passing bawah dan atas, servis, serta rotasi.'],['Bola basket','sports_basketball','Dribbling, passing, shooting, dan aturan permainan.'],['Bulu tangkis','sports_tennis','Servis, footwork, pukulan, dan strategi dasar.'],['Atletik','directions_run','Lari, lompat, dan lempar dengan teknik aman.'],['Senam','sports_gymnastics','Gerak dasar dan keseimbangan dengan pengawasan.'],['Kebugaran jasmani','fitness_center','Latihan daya tahan, kekuatan, dan kelenturan.'],['Kesehatan & gizi','health_and_safety','Pola hidup sehat, hidrasi, dan gizi seimbang.']];return `${heading('Materi PJOK','Perpustakaan ide pembelajaran untuk kelas Anda.',btn('Tambah materi','add-material'))}<div class="subnav">${['Semua materi','Permainan bola','Kebugaran','Kesehatan'].map((x,i)=>`<button class="${i===0?'active':''}" data-material-filter="${x}">${x}</button>`).join('')}</div><div class="subject-grid">${mats.map(([name,ico,desc])=>`<article class="subject-card"><div class="subject-icon">${icon(ico)}</div><h3>${name}</h3><p>${desc}</p><button class="btn btn-light" data-material="${name}" style="width:100%;padding:8px">Buka materi ${icon('arrow_forward')}</button></article>`).join('')}</div><div class="card" style="margin-top:15px;padding:12px 15px;color:#8290a1;font-size:10px">Materi ringkas adalah konten contoh untuk demonstrasi. Gambar dan video eksternal tidak disematkan.</div>`}
function tasksPage(){const tasks=get('tasks',[{title:'Kuis aturan sepak bola',class:'VII A',due:'2026-10-20',type:'Kuis teori',status:'Aktif'},{title:'Praktik teknik passing',class:'VII B',due:'2026-10-22',type:'Tugas praktik',status:'Draft'}]);return `${heading('Tugas & kuis','Buat kuis teori dan tugas praktik untuk siswa.',btn('Buat tugas','add-task'))}<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Tugas aktif',tasks.filter(t=>t.status==='Aktif').length,'assignment','tint-blue','Tugas sedang berjalan')}${stat('Menunggu penilaian','2','pending_actions','tint-orange','Perlu ditinjau guru')}${stat('Kuis dibuat',tasks.filter(t=>t.type.includes('Kuis')).length,'quiz','tint-green','Soal objektif')}</div><div class="card table-card"><div class="table-toolbar"><div><div class="panel-title">Daftar tugas dan kuis</div><div class="panel-sub">Penilaian praktik dilakukan dan dicatat oleh guru.</div></div></div><div class="table-wrap"><table><thead><tr><th>Nama tugas</th><th>Kelas</th><th>Jenis</th><th>Tenggat</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${tasks.map((t,i)=>`<tr><td><strong>${esc(t.title)}</strong></td><td>${esc(t.class)}</td><td>${esc(t.type)}</td><td>${t.due}</td><td><span class="status ${t.status==='Aktif'?'status-active':'status-Izin'}">${t.status}</span></td><td><button class="mini-btn" data-del-task="${i}">${icon('delete')}</button></td></tr>`).join('')}</tbody></table></div></div><div class="card panel" style="margin-top:14px"><div class="panel-title">Kuis singkat · Aturan permainan</div><p class="panel-sub">Contoh kuis interaktif untuk demonstrasi pemahaman materi sepak bola.</p><p style="font-size:12px;color:#40536b">Berapa pemain dalam satu tim sepak bola yang berada di lapangan saat permainan dimulai?</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-light quiz-answer">9 pemain</button><button class="btn btn-light quiz-answer" data-correct="true">11 pemain</button><button class="btn btn-light quiz-answer">12 pemain</button></div></div>`}
function reportsPage(){let avg=grades.length?Math.round(grades.reduce((a,g)=>a+Number(g.score),0)/grades.length):0;return `${heading('Laporan & analitik','Pantau kehadiran dan perkembangan belajar berdasarkan data tercatat.',btn('Ekspor laporan','report-csv','btn-light','download'))}<div class="attendance-controls" style="margin-bottom:14px"><select class="select-sm"><option>Periode: Semester ini</option><option>Bulan ini</option></select><select class="select-sm"><option>Semua kelas</option>${classNames().map(c=>`<option>${c}</option>`).join('')}</select><select class="select-sm"><option>Semua materi</option><option>Sepak bola</option><option>Bola voli</option></select></div><div class="stats">${stat('Nilai rata-rata',avg||'—','trending_up','tint-green','Dari penilaian yang tercatat')}${stat('Siswa terdata',students.length,'groups','tint-blue','Dalam data demo lokal')}${stat('Entri penilaian',grades.length,'fact_check','tint-purple','Di seluruh kelas')}${stat('Kehadiran bulan ini','92%','event_available','tint-orange','Ringkasan data contoh')}</div><div class="report-grid"><div class="card panel"><div class="panel-head"><div><div class="panel-title">Rata-rata nilai per kelas</div><div class="panel-sub">Berdasarkan entri nilai yang tersedia</div></div></div>${classNames().map(c=>{let gs=grades.filter(g=>g.kelas===c),v=gs.length?Math.round(gs.reduce((a,g)=>a+g.score,0)/gs.length):0;return `<div class="class-row"><span>${c} <small style="color:#99a4b2">· ${gs.length} nilai</small></span><div class="bar"><span style="width:${v||4}%"></span></div><strong>${v||'—'}</strong></div>`}).join('')}</div><div class="card panel"><div class="panel-head"><div><div class="panel-title">Perhatian untuk ditinjau</div><div class="panel-sub">Daftar otomatis berdasarkan nilai yang tercatat &lt; 75</div></div></div>${grades.filter(g=>g.score<75).map(g=>`<div class="activity"><div class="activity-icon" style="background:#fff3e5;color:#e99a3d">${icon('priority_high')}</div><div><strong>${esc(g.nama)} · ${esc(g.kelas)}</strong><small>${esc(g.materi)} · skor ${g.score}; pertimbangkan pendampingan</small></div></div>`).join('')||'<div class="empty">'+icon('verified')+'<p>Belum ada nilai di bawah 75 dalam data penilaian.</p></div>'}<div class="panel-sub" style="margin-top:10px">Laporan hanya merangkum data yang tersimpan. Kategori capaian dapat disesuaikan guru.</div></div></div>`}
function settingsPage(){return `${heading('Profil & pengaturan','Kelola identitas guru, sekolah, semester, dan preferensi aplikasi.')}<div class="grid-main"><div class="card panel"><div class="panel-title">Profil guru</div><p class="panel-sub">Informasi yang ditampilkan pada ruang kerja.</p><form id="profile-form" class="form-grid" style="margin-top:15px"><div class="field"><label>Nama lengkap</label><input name="nama" value="Dewi Guru, S.Pd." required /></div><div class="field"><label>Email</label><input type="email" name="email" value="dewi.guru@sekolah.sch.id" required /></div><div class="field"><label>Nama sekolah</label><input name="sekolah" value="SMP Negeri 1 Nusantara" required /></div><div class="field"><label>Tahun ajaran</label><select name="tahun"><option>2026/2027</option><option>2025/2026</option></select></div><div class="field"><label>Semester</label><select name="semester"><option>Ganjil</option><option>Genap</option></select></div><div class="field"><label>Tingkat pendidikan</label><select><option>SMP</option><option>SD</option><option>SMA/SMK</option></select></div><div class="field full"><button class="btn btn-primary">${icon('save')} Simpan profil</button></div></form></div><div class="card panel"><div class="panel-title">Pengaturan penilaian</div><p class="panel-sub">Contoh bobot awal. Atur sesuai kebijakan sekolah.</p><div class="schedule-item"><div class="lesson"><strong>Pengetahuan / teori</strong><small>Bobot contoh</small></div><input class="weight" type="number" value="25" min="0" max="100" style="width:62px;padding:7px;border:1px solid var(--line);border-radius:7px">%</div><div class="schedule-item"><div class="lesson"><strong>Keterampilan praktik</strong><small>Bobot contoh</small></div><input class="weight" type="number" value="40" min="0" max="100" style="width:62px;padding:7px;border:1px solid var(--line);border-radius:7px">%</div><div class="schedule-item"><div class="lesson"><strong>Kebugaran jasmani</strong><small>Bobot contoh</small></div><input class="weight" type="number" value="20" min="0" max="100" style="width:62px;padding:7px;border:1px solid var(--line);border-radius:7px">%</div><div class="schedule-item"><div class="lesson"><strong>Sikap & sportivitas</strong><small>Bobot contoh</small></div><input class="weight" type="number" value="15" min="0" max="100" style="width:62px;padding:7px;border:1px solid var(--line);border-radius:7px">%</div><button class="btn btn-light" style="margin-top:13px" data-action="save-weights">Simpan bobot</button><div class="panel-sub" style="margin-top:10px">Bobot di atas merupakan contoh dan dapat diubah. Nilai pada tabel adalah skor rubrik individual.</div></div></div><div class="card panel"><div class="panel-title">Penyimpanan dan privasi</div><p class="panel-sub">Prototipe ini menyimpan data pada localStorage di browser yang sedang digunakan. Data tidak tersinkron ke perangkat lain dan tidak memiliki cadangan server.</p><div class="actions" style="margin-top:13px">${btn('Unduh cadangan data','backup-data','btn-light','download')}${btn('Keluar','logout','btn-danger','logout')}</div></div>`}
function openModal(title,body,submitText='Simpan',onSave=()=>{}){const old=document.querySelector('.modal-backdrop');if(old)old.remove();let wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-close aria-label="Tutup">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="btn btn-light" data-close>Batal</button><button class="btn btn-primary">${icon('save')}${submitText}</button></div></form></section>`;document.body.append(wrap);wrap.querySelector('[name]')?.focus();wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close]'))wrap.remove()});wrap.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(onSave(fd)===false)return;wrap.remove();persist();shell()})}
const ff=(label,name,type='text',value='',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra} required /></div>`;
function studentModal(s=null){editing=s?.id;openModal(s?'Edit data siswa':'Tambah siswa',`<div class="form-grid">${ff('Nama lengkap','nama','text',s?.nama||'','minlength="2"')}${ff('Nomor induk siswa','nis','text',s?.nis||'','inputmode="numeric"') }<div class="field"><label for="f-kelas">Kelas</label><select id="f-kelas" name="kelas" required>${[...new Set([...classNames(),'VII A','VII B','VIII A','VIII B','IX A'])].map(c=>`<option ${s?.kelas===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Jenis kelamin</label><select name="gender"><option ${s?.gender==='Perempuan'?'selected':''}>Perempuan</option><option ${s?.gender==='Laki-laki'?'selected':''}>Laki-laki</option></select></div></div>`,s?'Simpan perubahan':'Tambah siswa',fd=>{let nama=fd.get('nama').trim(),nis=fd.get('nis').trim();if(!nama||!nis){toast('Nama dan nomor induk wajib diisi.');return false}if(students.some(x=>x.nis===nis&&x.id!==s?.id)){toast('Nomor induk tersebut sudah digunakan.');return false}let record={id:s?.id||nis,nama,nis,kelas:fd.get('kelas'),gender:fd.get('gender'),status:s?.status||'Aktif',initial:nama.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),scores:s?.scores||[78,82,86]};if(s)students=students.map(x=>x.id===s.id?record:x);else students.unshift(record);toast(s?'Data siswa diperbarui.':'Siswa berhasil ditambahkan.')} )}
function gradeModal(g=null){let s=students.find(x=>x.nis===g?.nis)||students[0];if(!s){toast('Tambahkan siswa terlebih dahulu.');return}openModal(g?'Edit nilai':'Input nilai PJOK',`<div class="form-grid"><div class="field full"><label>Siswa</label><select name="nis">${students.map(x=>`<option value="${x.nis}" ${x.nis===s.nis?'selected':''}>${esc(x.nama)} · ${x.kelas}</option>`).join('')}</select></div><div class="field"><label>Materi</label><select name="materi">${['Sepak bola','Bola voli','Bola basket','Bulu tangkis','Atletik','Kebugaran jasmani','Kesehatan dan gizi'].map(x=>`<option ${g?.materi===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Kategori penilaian</label><select name="kategori">${['Pengetahuan / teori','Keterampilan praktik','Kebugaran jasmani','Sikap, disiplin, sportivitas'].map(x=>`<option ${g?.kategori===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Komponen rubrik</label><input name="komponen" value="${esc(g?.komponen||'Passing')}" required /></div><div class="field"><label>Skor (0–100)</label><input name="score" type="number" min="0" max="100" value="${g?.score||''}" required /></div><div class="field"><label>Bobot (%)</label><input name="bobot" type="number" min="1" max="100" value="${g?.bobot||100}" required /></div><div class="field"><label>Semester</label><select name="semester"><option>Ganjil</option><option>Genap</option></select></div><div class="field full"><label>Catatan perkembangan</label><textarea name="catatan" placeholder="Catatan berdasarkan pengamatan guru">${esc(g?.catatan||'')}</textarea></div></div><p class="panel-sub">Nilai akhir rubrik: skor × bobot / bobot. Bobot akhir dapat dikonfigurasi di Pengaturan.</p>`,g?'Simpan perubahan':'Simpan nilai',fd=>{let student=students.find(x=>x.nis===fd.get('nis')),score=Number(fd.get('score')),bobot=Number(fd.get('bobot'));if(!student||score<0||score>100||bobot<1||bobot>100){toast('Periksa kembali skor (0–100) dan bobot (1–100).');return false}let rec={id:g?.id||'g'+Date.now(),nama:student.nama,nis:student.nis,kelas:student.kelas,materi:fd.get('materi'),kategori:fd.get('kategori'),komponen:fd.get('komponen'),score,bobot,semester:fd.get('semester'),catatan:fd.get('catatan').trim()};if(g)grades=grades.map(x=>x.id===g.id?rec:x);else grades.unshift(rec);toast(g?'Nilai diperbarui.':'Nilai berhasil disimpan.');})}
function scheduleModal(index=null){let s=index===null?null:schedule[index];openModal(s?'Edit jadwal':'Tambah jadwal',`<div class="form-grid"><div class="field"><label>Hari</label><select name="hari">${['Senin','Selasa','Rabu','Kamis','Jumat'].map(x=>`<option ${s?.hari===x?'selected':''}>${x}</option>`).join('')}</select></div>${ff('Waktu mulai','waktu','time',s?.waktu||'07:00')}<div class="field"><label>Kelas</label><select name="kelas">${classNames().map(x=>`<option ${s?.kelas===x?'selected':''}>${x}</option>`).join('')}</select></div>${ff('Materi / cabang olahraga','materi','text',s?.materi||'Sepak bola')}${ff('Lokasi pembelajaran','lokasi','text',s?.lokasi||'Lapangan utama')}<div class="field"><label>Warna agenda</label><select name="warna"><option value="green">Hijau</option><option value="orange">Oranye</option><option value="blue">Biru</option></select></div></div>`,s?'Simpan jadwal':'Tambah jadwal',fd=>{let rec={hari:fd.get('hari'),waktu:fd.get('waktu'),kelas:fd.get('kelas'),materi:fd.get('materi'),lokasi:fd.get('lokasi'),warna:fd.get('warna')};if(s)schedule[index]=rec;else schedule.push(rec);toast('Jadwal berhasil disimpan.')})}
function toast(message){let t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2800)}
function csvDownload(filename,rows){let csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);toast('File CSV berhasil diunduh.')}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;search='';shell()});document.getElementById('global-search')?.addEventListener('input',e=>{search=e.target.value;if(view!=='Siswa'){view='Siswa';shell();document.getElementById('student-search').focus()}else{document.getElementById('student-search').value=search;document.querySelector('#page').innerHTML=studentsPage();bind()}});document.getElementById('student-search')?.addEventListener('input',e=>{search=e.target.value;document.querySelector('#page').innerHTML=studentsPage();bind()});document.getElementById('class-filter')?.addEventListener('change',e=>{filterClass=e.target.value;document.querySelector('#page').innerHTML=studentsPage();bind()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{selectedStudent=b.dataset.student;view='Detail siswa';shell()});document.querySelectorAll('[data-edit-student]').forEach(b=>b.onclick=()=>studentModal(students.find(s=>s.id===b.dataset.editStudent)));document.querySelectorAll('[data-delete-student]').forEach(b=>b.onclick=()=>{let s=students.find(x=>x.id===b.dataset.deleteStudent);if(confirm(`Hapus data ${s.nama}? Tindakan ini tidak dapat dibatalkan.`)){students=students.filter(x=>x.id!==s.id);grades=grades.filter(g=>g.nis!==s.nis);persist();shell();toast('Data siswa dihapus.')}});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{activeDay=b.dataset.day;document.querySelector('#page').innerHTML=schedulePage();bind()});document.querySelectorAll('[data-edit-schedule]').forEach(b=>b.onclick=()=>scheduleModal(Number(b.dataset.editSchedule)));document.querySelectorAll('[data-del-schedule]').forEach(b=>b.onclick=()=>{if(confirm('Hapus jadwal ini?')){schedule.splice(Number(b.dataset.delSchedule),1);persist();shell();toast('Jadwal dihapus.')}});document.querySelectorAll('[data-class-students]').forEach(b=>b.onclick=()=>{filterClass=b.dataset.classStudents;view='Siswa';shell();document.getElementById('class-filter').value=filterClass});document.getElementById('grade-class')?.addEventListener('change',()=>{document.querySelector('#page').innerHTML=gradesPage();bind()});document.getElementById('attendance-class')?.addEventListener('change',()=>{document.querySelector('#page').innerHTML=attendancePage();bind()});document.getElementById('attendance-date')?.addEventListener('change',()=>{document.querySelector('#page').innerHTML=attendancePage();bind()});document.querySelectorAll('.quiz-answer').forEach(b=>b.onclick=()=>toast(b.dataset.correct?'Benar! Sepak bola dimainkan oleh 11 pemain per tim.':'Belum tepat. Coba ingat kembali aturan jumlah pemain.'));document.getElementById('profile-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Profil diperbarui untuk sesi prototipe ini.')})}
function handleAction(a){switch(a){case'menu':document.getElementById('sidebar').classList.toggle('open');break;case'add-student':studentModal();break;case'edit-current':studentModal(students.find(x=>x.id===selectedStudent));break;case'go-attendance':view='Presensi';shell();break;case'add-grade':gradeModal();break;case'add-schedule':scheduleModal();break;case'save-attendance':{let d=document.getElementById('attendance-date').value,c=document.getElementById('attendance-class').value,rec={...(attendance[d]||{})};document.querySelectorAll('.attend-status').forEach(el=>{rec[el.dataset.nis]={...(rec[el.dataset.nis]||{}),status:el.value}});document.querySelectorAll('.att-note').forEach(el=>{rec[el.dataset.nis]={...(rec[el.dataset.nis]||{}),note:el.value}});attendance[d]=rec;persist();toast('Presensi berhasil disimpan di browser ini.');shell();break}case'all-present':document.querySelectorAll('.attend-status').forEach(x=>x.value='Hadir');toast('Semua siswa ditandai hadir. Simpan untuk mencatat perubahan.');break;case'students-csv':csvDownload('data-siswa-pjok.csv',[['Nama','NIS','Kelas','Jenis kelamin','Status'],...students.map(s=>[s.nama,s.nis,s.kelas,s.gender,s.status])]);break;case'grades-csv':csvDownload('penilaian-pjok.csv',[['Nama','NIS','Kelas','Materi','Kategori','Komponen','Skor','Bobot','Catatan'],...grades.map(g=>[g.nama,g.nis,g.kelas,g.materi,g.kategori,g.komponen,g.score,g.bobot,g.catatan])]);break;case'attendance-csv':{let d=document.getElementById('attendance-date').value,c=document.getElementById('attendance-class').value,rec=attendance[d]||{};csvDownload('presensi-pjok.csv',[['Tanggal','Kelas','Nama','NIS','Status','Catatan'],...students.filter(s=>s.kelas===c).map(s=>[d,c,s.nama,s.nis,rec[s.nis]?.status||'Belum dicatat',rec[s.nis]?.note||''])]);break}case'report-csv':csvDownload('laporan-pjok.csv',[['Nama','Kelas','Materi','Kategori','Skor','Bobot','Catatan'],...grades.map(g=>[g.nama,g.kelas,g.materi,g.kategori,g.score,g.bobot,g.catatan])]);break;case'add-class':openModal('Tambah kelas',`<div class="form-grid">${ff('Nama kelas','kelas','text','','placeholder="Contoh: VIII C"')}${ff('Tingkat pendidikan','tingkat','text','SMP')}${ff('Lokasi belajar','lokasi','text','Lapangan utama')}</div>`, 'Tambah kelas',fd=>{let c=fd.get('kelas').trim().toUpperCase();if(!c||classNames().includes(c)){toast('Nama kelas kosong atau sudah tersedia.');return false}classes.push(c);toast('Kelas berhasil dibuat.')});break;case'add-task':openModal('Buat tugas atau kuis',`<div class="form-grid">${ff('Nama tugas','title','text','','minlength="3"')}<div class="field"><label>Kelas</label><select name="kelas">${classNames().map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Jenis</label><select name="type"><option>Kuis teori</option><option>Tugas teori</option><option>Tugas praktik</option></select></div>${ff('Tenggat waktu','due','date',shortDate)}<div class="field full"><label>Deskripsi / instruksi</label><textarea name="desc" placeholder="Jelaskan tujuan dan instruksi tugas"></textarea></div></div>`, 'Buat tugas',fd=>{let tasks=get('tasks',[]);tasks.unshift({title:fd.get('title'),class:fd.get('kelas'),type:fd.get('type'),due:fd.get('due'),status:'Aktif'});localStorage.setItem('pjok_tasks',JSON.stringify(tasks));toast('Tugas berhasil dibuat.')});break;case'add-material':openModal('Tambah materi PJOK',`<div class="form-grid">${ff('Judul materi','title')}${ff('Kategori','category')}<div class="field full"><label>Tujuan pembelajaran dan teknik dasar</label><textarea name="desc" required></textarea></div><div class="field full"><label>Tautan video (opsional)</label><input type="url" name="url" placeholder="https://..." /></div></div>`,'Tambah materi',()=>toast('Materi tersimpan untuk demonstrasi sesi ini.'));break;case'weights':view='Pengaturan';shell();break;case'save-weights':{let vals=[...document.querySelectorAll('.weight')].map(x=>Number(x.value));if(vals.some(x=>x<0||x>100)||vals.reduce((a,b)=>a+b,0)!==100)toast('Total bobot perlu tepat 100%. Saat ini: '+vals.reduce((a,b)=>a+b,0)+'%.');else{localStorage.setItem('pjok_weights',JSON.stringify(vals));toast('Bobot penilaian berhasil disimpan.')}break}case'backup-data':{let blob=new Blob([JSON.stringify({students,classes,grades,schedule,attendance,tasks:get('tasks',[])},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cadangan-pjok-smart.json';a.click();URL.revokeObjectURL(url);toast('Cadangan data diunduh.');break}case'logout':sessionStorage.removeItem('pjok_logged');shell();toast('Anda keluar dari sesi demo.');break;case'notify':toast('Belum ada notifikasi baru.');break;case'help':toast('Pilih menu di samping untuk mengelola kelas, presensi, dan nilai.');break;case'import-csv':{let inp=document.createElement('input');inp.type='file';inp.accept='.csv,text/csv';inp.onchange=()=>{let file=inp.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{let lines=String(reader.result).split(/\r?\n/).slice(1).filter(Boolean),added=0;for(let line of lines){let cols=line.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)?.filter(x=>x!==',').map(x=>x.replace(/,$/,'').replace(/^"|"$/g,'').replace(/""/g,'"'))||[];let [nama,nis,kelas,gender='Perempuan',status='Aktif']=cols;if(nama&&nis&&!students.some(s=>s.nis===nis)){students.push({id:nis,nama,nis,kelas:kelas||'VII A',gender,status,initial:nama.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),scores:[]});added++}}persist();shell();toast(`${added} siswa berhasil diimpor.`)};reader.readAsText(file)};inp.click();break}default:break}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-edit-grade]');if(b)gradeModal(grades.find(g=>g.id===b.dataset.editGrade));b=e.target.closest('[data-del-grade]');if(b&&confirm('Hapus entri nilai ini?')){grades=grades.filter(g=>g.id!==b.dataset.delGrade);persist();shell();toast('Entri nilai dihapus.')}b=e.target.closest('[data-del-task]');if(b&&confirm('Hapus tugas ini?')){let tasks=get('tasks',[]);tasks.splice(Number(b.dataset.delTask),1);localStorage.setItem('pjok_tasks',JSON.stringify(tasks));shell();toast('Tugas dihapus.')}b=e.target.closest('[data-material]');if(b){let title=b.dataset.material;openModal(title,`<div class="subject-icon" style="height:120px">${icon('sports')}</div><h3>Tujuan pembelajaran</h3><p class="page-desc">Mengenal teknik dasar ${esc(title.toLowerCase())} dan mempraktikkannya dengan aman serta sportif.</p><h3>Teknik dasar</h3><p class="page-desc">Pemanasan, posisi siap, penguasaan teknik, dan pendinginan sesuai kondisi siswa.</p><h3>Tips keselamatan</h3><p class="page-desc">Pastikan area aman, lakukan pemanasan, gunakan alat sesuai instruksi guru, dan sesuaikan intensitas.</p><div class="demo-note">Konten ringkas contoh. Lengkapi materi berdasarkan kurikulum sekolah.</div>`,'Tutup',()=>true)}});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();sessionStorage.setItem('pjok_logged','1');document.querySelector('.overlay-login')?.remove();toast('Selamat datang di PJOK SMART.')}});
document.addEventListener('click',e=>{let filter=e.target.closest('[data-material-filter]');if(!filter)return;document.querySelectorAll('[data-material-filter]').forEach(x=>x.classList.toggle('active',x===filter));let mode=filter.dataset.materialFilter;document.querySelectorAll('.subject-card').forEach(card=>{let title=card.querySelector('h3').textContent,show=mode==='Semua materi'||(mode==='Permainan bola'&&['Sepak bola','Bola voli','Bola basket','Bulu tangkis'].includes(title))||(mode==='Kebugaran'&&['Atletik','Senam','Kebugaran jasmani'].includes(title))||(mode==='Kesehatan'&&title==='Kesehatan & gizi');card.hidden=!show})});
shell();
